changeSet.sql:
DO $$ DECLARE v_acc RECORD; v_total_quiz_stars INT; v_badge_count INT; BEGIN SELECT COALESCE(COUNT(*) * 3, 675) INTO v_total_quiz_stars FROM learning_unit WHERE type = 'QUIZ'; SELECT COUNT(*) INTO v_badge_count FROM reward_catalog WHERE is_active = true;
FOR v_acc IN SELECT id, email FROM account WHERE email IN ('student@fsa.com', 'lequocbaotxdh@gmail.com') OR id = '00000000-0000-0000-0002-000000000002' LOOP -- 1. Mark entry test as completed UPDATE account SET has_done_entry_test = true WHERE id = v_acc.id;
-- 2. Unlock and complete all learning units of type 'LEVEL' INSERT INTO account_learning_unit (id, created_at, updated_at, created_by, updated_by, account_id, learning_unit_id, stars_earned, is_completed, highest_score, is_unlocked) SELECT gen_random_uuid(), NOW(), NOW(), 'system', 'system', v_acc.id, lu.id, 3, true, 100.00, true FROM learning_unit lu WHERE lu.type = 'LEVEL' ON CONFLICT (account_id, learning_unit_id) DO UPDATE SET stars_earned = 3, is_completed = true, highest_score = 100.00, is_unlocked = true, updated_at = NOW();
-- 3. Unlock and complete all learning units of type 'QUIZ' INSERT INTO account_learning_unit (id, created_at, updated_at, created_by, updated_by, account_id, learning_unit_id, stars_earned, is_completed, highest_score, is_unlocked) SELECT gen_random_uuid(), NOW(), NOW(), 'system', 'system', v_acc.id, lu.id, 3, true, 100.00, true FROM learning_unit lu WHERE lu.type = 'QUIZ' ON CONFLICT (account_id, learning_unit_id) DO UPDATE SET stars_earned = 3, is_completed = true, highest_score = 100.00, is_unlocked = true, updated_at = NOW();
-- 4. Unlock all active rewards (badges and achievements) INSERT INTO account_reward (id, account_id, reward_catalog_id, status, progress_value, unlocked_at, created_at, updated_at) SELECT gen_random_uuid(), v_acc.id, rc.id, 'UNLOCKED', 100, NOW(), NOW(), NOW() FROM reward_catalog rc WHERE rc.is_active = true ON CONFLICT (account_id, reward_catalog_id) DO UPDATE SET status = 'UNLOCKED', progress_value = 100, unlocked_at = COALESCE(account_reward.unlocked_at, NOW()), updated_at = NOW();
-- 5. Update account table directly to reflect all stars, points (total_experience), streak, and badges UPDATE account SET total_experience = 50000, total_stars = v_total_quiz_stars, badge_count = v_badge_count, max_streak_days = 30, current_streak_days = 30, last_activity_date = CURRENT_DATE, updated_at = NOW() WHERE id = v_acc.id; END LOOP; END $$;
